214	{
215	    uint32_t sleep_ms;
216	
217	    sleep_ms = lv_timer_handler();
218	
219	    if(sleep_ms == LV_NO_TIMER_READY) {
220	        uv_timer_stop(handle);
221	        return;
222	    }
223	
224	    /* Prevent busy loops. */
225	
226	    if(sleep_ms == 0) {
227	        sleep_ms = 1;
228	    }
229	
230	    LV_LOG_TRACE("sleep_ms = %" LV_PRIu32, sleep_ms);
231	    uv_timer_start(handle, lv_nuttx_uv_timer_cb, sleep_ms, 0);
232	}
