323	static void lv_nuttx_uv_disp_vsync_request_cb(lv_event_t * e)
324	{
325	    lv_nuttx_uv_vsync_ctx_t * vsync_ctx = lv_event_get_user_data(e);
326	    void * param = lv_event_get_param(e);
327	
328	    if(param) {
329	        if(vsync_ctx->vsync_req_count < 0) return;
330	
331	        if(vsync_ctx->vsync_req_count == 0) {
332	            LV_LOG_INFO("enabled");
333	            if(vsync_ctx->fd > 0) {
334	                uv_poll_start(&vsync_ctx->vsync_poll, UV_PRIORITIZED, lv_nuttx_uv_vsync_poll_cb);
335	            }
336	            lv_timer_resume(vsync_ctx->vsync_timer);
337	        }
338	        vsync_ctx->vsync_req_count++;
339	    }
340	    else {
341	        if(vsync_ctx->vsync_req_count == 0) return;
342	
343	        vsync_ctx->vsync_req_count--;
344	        if(vsync_ctx->vsync_req_count == 0) {
345	            LV_LOG_INFO("disabled");
346	            if(vsync_ctx->fd > 0) {
347	                uv_poll_stop(&vsync_ctx->vsync_poll);
348	            }
349	            lv_timer_pause(vsync_ctx->vsync_timer);
350	        }
351	    }
352	}
