354	static int _lv_nuttx_uv_vsync_init(lv_nuttx_uv_t * uv_info, lv_nuttx_uv_ctx_t * uv_ctx)
355	{
356	    LV_ASSERT_NULL(uv_info);
357	    LV_ASSERT_NULL(uv_ctx);
358	
359	    lv_nuttx_uv_vsync_ctx_t * vsync_ctx = &uv_ctx->vsync_ctx;
360	    vsync_ctx->vsync_timer = lv_timer_create(lv_nuttx_uv_vsync_timer_cb,
361	                                             LV_NUTTX_VSYNC_TIMER_PERIOD, NULL);
362	    if(vsync_ctx->vsync_timer == NULL) {
363	        LV_LOG_ERROR("lv_nuttx_uv_vsync_init fail");
364	        return -ENOMEM;
365	    }
366	    lv_timer_pause(vsync_ctx->vsync_timer);
367	
368	    uv_loop_t * loop = uv_info->loop;
369	
370	    if(loop != NULL) {
371	        vsync_ctx->fd = *(int *)(lv_intptr_t)lv_display_get_driver_data(uv_info->disp);
372	        vsync_ctx->vsync_poll.data = vsync_ctx;
373	        uv_poll_init(loop, &vsync_ctx->vsync_poll, vsync_ctx->fd);
374	        uv_ctx->ref_count++;
375	    }
376	
377	    LV_LOG_USER("lvgl vsync start OK");
378	    lv_display_add_event_cb(uv_info->disp, lv_nuttx_uv_disp_vsync_request_cb, LV_EVENT_VSYNC_REQUEST, vsync_ctx);
379	    return 0;
380	}
