394	static int lv_nuttx_uv_fb_init(lv_nuttx_uv_t * uv_info, lv_nuttx_uv_ctx_t * uv_ctx)
395	{
396	    uv_loop_t * loop = uv_info->loop;
397	    lv_display_t * disp = uv_info->disp;
398	
399	    LV_ASSERT_NULL(uv_ctx);
400	    LV_ASSERT_NULL(disp);
401	    LV_ASSERT_NULL(loop);
402	
403	    lv_nuttx_uv_fb_ctx_t * fb_ctx = &uv_ctx->fb_ctx;
404	    fb_ctx->fd = *(int *)lv_display_get_driver_data(disp);
405	
406	    if(fb_ctx->fd <= 0) {
407	        LV_LOG_USER("skip uv fb init.");
408	        return 0;
409	    }
410	
411	    if(!lv_display_get_refr_timer(disp)) {
412	        LV_LOG_ERROR("disp refr_timer is NULL");
413	        return -EINVAL;
414	    }
415	
416	    /* Remove default refr timer. */
417	    lv_display_delete_refr_timer(disp);
418	
419	    fb_ctx->fb_poll.data = uv_ctx;
420	    uv_poll_init(loop, &fb_ctx->fb_poll, fb_ctx->fd);
421	    uv_ctx->ref_count++;
422	    uv_poll_start(&fb_ctx->fb_poll, UV_WRITABLE, lv_nuttx_uv_disp_poll_cb);
423	
424	    LV_LOG_USER("lvgl fb loop start OK");
425	
426	    /* Register for the invalidate area event */
427	
428	    lv_display_add_event_cb(disp, lv_nuttx_uv_disp_refr_req_cb, LV_EVENT_REFR_REQUEST, fb_ctx);
429	
430	    return 0;
431	}
