457	static int lv_nuttx_uv_input_init(lv_nuttx_uv_t * uv_info, lv_nuttx_uv_ctx_t * uv_ctx)
458	{
459	    uv_loop_t * loop = uv_info->loop;
460	    lv_indev_t * indev = uv_info->indev;
461	
462	    if(indev == NULL) {
463	        LV_LOG_USER("skip uv input init.");
464	        return 0;
465	    }
466	
467	    LV_ASSERT_NULL(uv_ctx);
468	    LV_ASSERT_NULL(loop);
469	
470	    if(lv_indev_get_mode(indev) == LV_INDEV_MODE_EVENT) {
471	        LV_LOG_ERROR("input device has been running in event-driven mode");
472	        return -EINVAL;
473	    }
474	
475	    lv_nuttx_uv_input_ctx_t * input_ctx = &uv_ctx->input_ctx;
476	    input_ctx->fd = *(int *)lv_indev_get_driver_data(indev);
477	    if(input_ctx->fd <= 0) {
478	        LV_LOG_ERROR("can't get valid input fd");
479	        return 0;
480	    }
481	
482	    input_ctx->indev = indev;
483	    lv_indev_set_mode(indev, LV_INDEV_MODE_EVENT);
484	
485	    input_ctx->input_poll.data = uv_ctx;
486	    uv_poll_init(loop, &input_ctx->input_poll, input_ctx->fd);
487	    uv_ctx->ref_count++;
488	    uv_poll_start(&input_ctx->input_poll, UV_READABLE, lv_nuttx_uv_input_poll_cb);
489	
490	    LV_LOG_USER("lvgl input loop start OK");
491	
492	    return 0;
493	}
